"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";

type Review = { id: string; booking_id: string; rating: number; review_text: string; vendor_response: string | null; created_at: string };
export function VendorReviewsPanel({ vendorId }: { vendorId: string }) {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const load = async () => { const { data, error: queryError } = await supabase.from("vendor_reviews_participant").select("id,booking_id,rating,review_text,vendor_response,created_at").eq("vendor_profile_id", vendorId).order("created_at", { ascending: false }); if (queryError) throw new Error("Reviews could not be loaded. Apply the vendor business migration if it is not deployed."); setReviews(data ?? []); };
  useEffect(() => { void load().catch((cause) => setError(cause instanceof Error ? cause.message : "Reviews could not be loaded.")); }, [vendorId]);
  const respond = async (id: string) => { const responseText = drafts[id]?.trim(); if (!responseText) return; setBusy(id); setError(null); try { const response = await fetch(`/api/vendors/reviews/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ response: responseText }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Response could not be saved."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Response could not be saved."); } finally { setBusy(null); } };
  const average = reviews.length ? reviews.reduce((total, review) => total + review.rating, 0) / reviews.length : null;
  return <section className="space-y-4 rounded-3xl border border-[#EAD2B0] bg-[#FFFCF6] p-5 dark:border-[#4D3331] dark:bg-[#241918]"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="font-serif text-2xl font-bold text-[#681B1D] dark:text-[#EAD2B0]">Customer reviews</h2><p className="mt-1 text-sm text-[#7D6B63]">Only reviews tied to completed bookings are eligible.</p></div><div className="text-right"><b className="font-serif text-3xl text-[#681B1D] dark:text-[#EAD2B0]">{average === null ? "—" : average.toFixed(1)}</b><p className="text-xs text-[#7D6B63]">{reviews.length} review{reviews.length === 1 ? "" : "s"}</p></div></div>{error && <p role="alert" className="text-sm text-rose-700">{error}</p>}{reviews.map((review) => <article key={review.id} className="space-y-3 rounded-2xl border border-[#EAD2B0] p-4 dark:border-[#4D3331]"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{"★".repeat(review.rating)}<span className="text-[#B77A36]">{"☆".repeat(5 - review.rating)}</span></p><p className="mt-1 text-sm">{review.review_text}</p></div><time className="shrink-0 text-xs text-[#7D6B63]">{new Date(review.created_at).toLocaleDateString("en-IN")}</time></div>{review.vendor_response ? <p className="rounded-xl bg-[#FFF3E3] p-3 text-sm dark:bg-[#1A1211]"><b>Your response</b><span className="mt-1 block">{review.vendor_response}</span></p> : <div className="space-y-2"><textarea maxLength={2000} className="w-full rounded-xl border border-[#EAD2B0] bg-[#FFF3E3] p-3 text-sm dark:border-[#4D3331] dark:bg-[#1A1211]" placeholder="Write a public response" value={drafts[review.id] ?? ""} onChange={(event) => setDrafts({ ...drafts, [review.id]: event.target.value })}/><button disabled={busy === review.id || !drafts[review.id]?.trim()} onClick={() => void respond(review.id)} className="rounded-xl bg-[#681B1D] px-4 py-2 text-xs font-semibold text-white disabled:opacity-50">{busy === review.id ? "Saving…" : "Post response"}</button></div>}</article>)}{!reviews.length && !error && <p className="rounded-2xl bg-[#FFF3E3] p-6 text-center text-sm text-[#7D6B63] dark:bg-[#1A1211]">No customer reviews yet. Reviews become available after a completed booking.</p>}</section>;
}
